import math

def is_power_of_p(n, p):
    """Checks if n is a power of p (p^k, k >= 1)."""
    if n <= 0:
        return False
    if n == 1: # Since a, b are positive and p>2, the powers should be at least p^1
        return False

    # Handle the case p=2 just in case, though problem states p>2
    if p == 2:
        return (n > 0) and ((n & (n - 1)) == 0)

    current = n
    while current > 1:
        if current % p != 0:
            return False
        current //= p
    return current == 1

# Function to test solutions
def test_case(p, a, b):
    if a > b:
        return None # Constraint a <= b

    # Check condition 1: a^(p-1) + b = p^x
    try:
        LHS1 = a**(p-1) + b
    except OverflowError:
        return None # Too large for standard integer types

    is_pow1 = is_power_of_p(LHS1, p)

    # Check condition 2: b^(p-1) + a = p^y
    try:
        LHS2 = b**(p-1) + a
    except OverflowError:
        return None

    is_pow2 = is_power_of_p(LHS2, p)

    if is_pow1 and is_pow2:
        return (p, a, b)
    else:
        return None

# Test for p=3 (p-1 = 2)
print("--- Testing p=3 ---")
solutions_p3 = []
for a in range(1, 11):
    for b in range(a, 11):
        sol = test_case(3, a, b)
        if sol:
            solutions_p3.append(sol)

print(f"Solutions found for p=3 (a, b <= 10): {solutions_p3}")

# Test for p=5 (p-1 = 4)
print("\n--- Testing p=5 ---")
solutions_p5 = []
for a in range(1, 6): # Reduced upper bound for p=5 since powers grow faster
    for b in range(a, 6):
        sol = test_case(5, a, b)
        if sol:
            solutions_p5.append(sol)

print(f"Solutions found for p=5 (a, b <= 5): {solutions_p5}")
